import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { paginateNonPaginatedData, paginationDataRes, paginationRes } from '../../interfaces/pagination.interface';

@Injectable({
  providedIn: 'root'
})
export class PaginationService {

  constructor(public sStore: SecureStorageService, private http: HttpClient, public tost: TostbarService) { }


  async getPagination(nBundledetailid: string): Promise<paginationRes> {
    try {
      const params = new HttpParams().set('nBundledetailid', nBundledetailid);
      const res: paginationRes = await firstValueFrom(
        this.http.get<paginationRes>(
          `${environment.cloudUrl}${environment.coreservice}/bundles/paginationdata`,
          { params: params }
        )
      );

      return res[0];
    } catch (err) {
      return null;
    }
  }

  async submitPagination(mdl: paginationDataRes): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<paginationRes>(`${environment.paginationservice}/paginationdata/pagination`, //${environment.cloudUrl}
          mdl)
      );
      if (res && res.msg == 1) {
        // this.tost.openSnackBar(res.value + 'success', '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`Pagination failed ${err}`, 'E');
      return false;
    }
  }


  async stopPagination(mdl: paginationDataRes): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<paginationRes>(`${environment.paginationservice}/paginationdata/stoppagination`, //${environment.cloudUrl}
          mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`Pagination failed ${err}`, 'E');
      return false;
    }
  }

  async getPaginationData(nCaseid: string): Promise<paginationRes> {
    try {
      let params = new HttpParams()
      params = params.set('nCaseid', nCaseid);
      // params = params.set('nPtaskid', 0);
      const res: paginationRes = await firstValueFrom(
        this.http.get<paginationRes>(
          `${environment.paginationservice}/paginationdata/getpagination`, //${environment.cloudUrl}
          { params: params }
        )
      );

      return res;
    } catch (err) {
      return null;
    }
  }


  async paginateNonPaginated(mdl: paginateNonPaginatedData): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<paginationRes>(`${environment.paginationservice}/paginationdata/paginationNonPaginated`, //${environment.cloudUrl}
          mdl)
      );
      if (res && res.msg == 1) {
        // this.tost.openSnackBar(res.value + 'success', '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`Pagination failed ${err}`, 'E');
      return false;
    }
  }


}

